'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {data:null,inventory:[],thematic:[],urbanProvenance:null,observationCounts:null,theme:'reference',overlays:{boundary:true,settlement:true,road:true,river:true,coast:true},vectorLayers:{},raster:null,labels:null,labelsVisible:true,urbanMode:'after',urbanBlend:100,view:'themes',rasterLoadToken:0,rasterPending:0,bookmarks:[]};
const colors={boundary:'#526c3f',settlement:'#344e36',road:'#b79660',river:'#709eab',coast:'#4c8791'};
const GSI_RIGHTS_WARNING='GSI web-display and redistribution rights remain unresolved. Attribution and this caveat do not grant permission. This is a non-official atlas, not a GSI or KSDMA product.';
const themeDefs=[
 {id:'reference',title:'Reference map',subtitle:'Boundary, places & connections',number:'01',icon:'reference',heading:'Reference geography',description:'Find your bearings along the Malabar coast. Explore the district boundary, mapped settlements, roads and rivers.'},
 {id:'landcover',title:'Land cover',subtitle:'Satellite-derived classes',number:'02',icon:'cover',heading:'Satellite-derived classes',description:'Explore a satellite-derived classification of the landscape. Classes describe a modelled land-cover product, not verified conditions on the ground.'},
 {id:'elevation',title:'Elevation',subtitle:'Surface height in metres',number:'03',icon:'terrain',heading:'Where the land rises',description:'Read the transition from coastal lowlands to the Western Ghats. Surface elevation includes the influence of vegetation and structures.'},
 {id:'slope',title:'Slope',subtitle:'Terrain steepness in degrees',number:'04',icon:'terrain',heading:'Reading the gradient',description:'Terrain steepness derived from elevation in a metric projected grid. Resolution affects slope; this is not a site-level engineering assessment.'},
 {id:'coastal',title:'Coastal geography',subtitle:'Along the Arabian Sea',number:'05',icon:'coast',heading:'At the water’s edge',description:'Explore mapped coastal features and nearby settlements. A mapped coastline is not a surveyed tidal boundary, and implies no erosion or flood-risk designation.'},
 {id:'urban',title:'Urban change · 2019–2025',subtitle:'Satellite comparison · 2019 → 2025',number:'06',icon:'reference',heading:'Urban change · 2019–2025',description:'Compare matching January–March satellite composites. Switch dates or blend the images to inspect changes. Candidate built-up gains are model signals, not verified new buildings.'},
 {id:'population',title:'Population & society',subtitle:'Verified statistical units needed',number:'07',icon:'reference',heading:'People, not just polygons'},
 {id:'landslide',title:'Landslide susceptibility',subtitle:'GSI zones · exploratory, not a warning',number:'08',icon:'terrain',heading:'Reading susceptibility zones',description:'GSI susceptibility zones show relative susceptibility classes, not probabilities or predicted events. They are exploratory district-scale evidence—not a live alert, a safe-land designation, or a site assessment.'}
];
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function getJSON(url,required=true){const r=await fetch(url);if(!r.ok){if(!required)return null;throw Error(`Could not load ${url} (HTTP ${r.status}).`);}return r.json();}
function themeData(id){return state.thematic.find(x=>x.id===id || (id==='landcover' && x.id==='land-cover'));}
function available(id){if(id==='reference')return !!state.data;if(id==='coastal')return state.data?.features.some(f=>f.properties.kind==='coast');return !!themeData(id);}
function thumb(icon){return `<span class="thumb ${icon}">${['reference'].includes(icon)?'<svg viewBox="0 0 40 40"><path d="m0 12 12-4 13 9 15-5M0 29l12-4 12 7 16-6M12 0v40M25 0v40"/><path d="M0 19 40 9M0 35l40-18" stroke="#b1bc9b"/></svg>':''}</span>`;}
function renderThemes(filter=''){
 const defs=themeDefs.filter(t=>(t.title+' '+t.subtitle).toLowerCase().includes(filter.toLowerCase()));
 $('#theme-list').innerHTML=defs.map(t=>`<button class="theme-card ${state.theme===t.id?'selected':''} ${!available(t.id)?'unavailable':''}" data-theme="${t.id}" aria-pressed="${state.theme===t.id}">${thumb(t.icon)}<span><strong>${t.title}</strong><small>${t.subtitle}</small></span>${available(t.id)?'<span class="selected-dot" aria-hidden="true"></span>':'<span class="lock-label">Not ready</span>'}</button>`).join('')||'<p class="loading-text">No matching map themes.</p>';
 $('#theme-list').querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>selectTheme(b.dataset.theme)));
 $('#layer-count').textContent=themeDefs.filter(t=>available(t.id)).length;
}
function renderOverlays(){state.view='overlays';const rows=Object.keys(state.overlays).filter(k=>state.data.features.some(f=>f.properties.kind===k)).map(k=>`<label class="overlay-row">${({boundary:'District boundary',settlement:'Settlements',road:'Major roads',river:'Rivers',coast:'Coastline'})[k]}<input type="checkbox" data-overlay="${k}" ${state.overlays[k]?'checked':''}></label>`).join('');$('#theme-list').innerHTML='<div class="eyebrow" style="padding:9px 10px">REFERENCE FEATURES</div>'+rows+`<label class="overlay-row">Place labels<input type="checkbox" id="labels-toggle-overlay" ${state.labelsVisible?'checked':''}></label>`;$('#theme-list').querySelectorAll('input[data-overlay]').forEach(i=>i.onchange=()=>{state.overlays[i.dataset.overlay]=i.checked;updateMap();});const lt=$('#labels-toggle-overlay');if(lt)lt.onchange=()=>setLabelsVisible(lt.checked);}
function setCatalogue(view){state.view=view;$('#maps-tab').classList.toggle('active',view==='themes');$('#overlays-tab').classList.toggle('active',view==='overlays');$('#maps-tab').setAttribute('aria-pressed',view==='themes');$('#overlays-tab').setAttribute('aria-pressed',view==='overlays');view==='themes'?renderThemes():renderOverlays();}
function refLegend(){const labels={boundary:'District boundary',settlement:'Mapped settlements',road:'Major mapped roads',river:'Rivers & waterways',coast:'Mapped coastline'};return Object.entries(labels).filter(([k])=>state.overlays[k]&&state.data.features.some(f=>f.properties.kind===k)).map(([k,v])=>({label:v,color:colors[k],type:k==='settlement'?'point':k==='boundary'?'line':'fill'}));}
function activeLegend(){const t=themeData(state.theme);if(state.theme==='urban'&&state.urbanMode!=='candidates')return t?.imageryLegend||[{label:'Natural colour · identical display stretch',color:'#75866f'}];return t?.legend?.length?t.legend:refLegend();}
function renderLegend(){const def=themeDefs.find(t=>t.id===state.theme);const list=[...activeLegend(),...(window.atlas?.elections?.exportFeatures().length?[{label:'MLA constituency borders (indicative)',color:'#576d45',type:'line'}]:[])];$('#legend').innerHTML=`<h3>${esc(def.title)}</h3>${list.map(l=>`<div class="legend-item"><i class="${l.type||''}" style="background:${l.type?'none':esc(l.color)};${l.type==='line'?`border-color:${esc(l.color)}`:l.type==='point'?`background:${esc(l.color)}`:''}"></i><span>${esc(l.label)}</span></div>`).join('')}<small>${state.theme==='landslide'?'GSI 2022 · unmapped ≠ safe · not a live warning':state.theme==='urban'&&state.urbanMode!=='candidates'?'Natural colour · Jan–Mar 2019 / Jan–Mar 2025 · same display stretch':themeData(state.theme)?'Published classes / see source notes':'Reference features · not exhaustive'}</small>`;}
function detail(label,value){return `<dl class="detail"><dt>${label}</dt><dd>${esc(value)}</dd></dl>`;}
function urbanSources(t){if(state.urbanMode==='before')return[{image:t.beforeImage||t.image,opacity:1}];if(state.urbanMode==='candidates')return[{image:t.gainImage,opacity:1}];return[{image:t.beforeImage||t.image,opacity:1},{image:t.afterImage||t.image,opacity:state.urbanBlend/100}];}
function renderUrbanControls(){const b=$('#urban-controls'),t=themeData('urban');if(!b)return;b.hidden=!(state.theme==='urban'&&t);if(state.theme!=='urban'){$('#raster-caption').textContent='';return;}if(!t)return;b.querySelectorAll('[data-urban-mode]').forEach(x=>{x.disabled=x.dataset.urbanMode==='candidates'&&!t.gainImage;x.classList.toggle('active',x.dataset.urbanMode===state.urbanMode);x.setAttribute('aria-pressed',x.dataset.urbanMode===state.urbanMode)});$('#urban-blend').disabled=state.urbanMode!=='after';$('#urban-blend').value=state.urbanBlend;$('#urban-blend-value').textContent=state.urbanBlend+'%';$('#raster-caption').textContent=state.urbanMode==='before'?'Before · 2019':state.urbanMode==='candidates'?'Candidate built-up gains · model signals':`2019 → 2025 · ${state.urbanBlend}% after`;const tl=$('#urban-timeline');if(tl)tl.innerHTML=urbanTimeline();}
function setUrbanMode(mode){const t=themeData('urban');if(!t||(mode==='candidates'&&!t.gainImage))return;state.urbanMode=mode;if(mode==='before')state.urbanBlend=0;if(mode==='after')state.urbanBlend=100;updateMap();updateInfo();}
function updateInfo(){const d=themeDefs.find(t=>t.id===state.theme);const t=themeData(state.theme);$('#info-title').textContent=d.heading;$('#info-description').textContent=d.description;$('#field-number').textContent=d.number+' / '+d.title;$('#map-title').textContent=d.title;$('#map-tag').textContent=state.theme==='landslide'?'Not a live warning':'Exploratory';$('#export-title').value='Kozhikode · '+d.title;const extra=state.theme==='landslide'?`<div class="landslide-disclaimer"><strong>Important limitation</strong><p>Relative susceptibility zones are not probabilities, forecasts, alerts, safe-land maps, or site assessments. Unmapped areas are not shown as safe.</p><p><strong>Source:</strong> GSI 2022 / Kerala State Disaster Management Authority (KSDMA).</p><p><strong>Rights:</strong> ${GSI_RIGHTS_WARNING}</p><p><a href="https://sdma.kerala.gov.in/" target="_blank" rel="noopener noreferrer">Official Kerala State Disaster Management Authority ↗</a></p></div>`:'';$('#info-details').innerHTML=t?[detail('Source',t.source),detail('Observation period',t.period),detail('Display resolution',t.resolution),detail('Method',t.method),detail('Layer limitations',state.theme==='landslide'?(t.limitations||'Relative susceptibility zones; unmapped areas are not safe; not a live warning or site assessment.'):'See source notes')].join('')+extra:[detail('Coverage','Kozhikode district, Kerala'),detail('Data type','Open boundary & mapped features'),detail('Spatial reference','WGS 84 · display EPSG:3857')].join('');$('#feature-box').innerHTML='<span class="eyebrow">Look a little closer</span><p>'+ (t?'Click anywhere on the map to inspect coordinates, surface elevation, slope, land cover and the nearest named atlas feature. Source and product date accompany every reading.':'Click anywhere to inspect its coordinates, terrain, land cover and nearest named atlas feature.')+'</p>';renderLegend();}
function inspectFeature(f,layer){const p=f.properties;const html=`<strong>${esc(p.name||'Unnamed feature')}</strong><br>${esc(p.kind)}<br><span style="font-size:10px;color:#7b876e">${esc(p.source||'See data provenance')}</span>`;layer.bindPopup(html);layer.on('click',()=>{const element=layer.getElement?.();if(element&&!matchMedia('(prefers-reduced-motion: reduce)').matches)element.animate([{opacity:.4},{opacity:1}],{duration:300,easing:'ease-out'});$('#feature-box').innerHTML=`<span class="eyebrow">Identified feature</span><strong>${esc(p.name||'Unnamed feature')}</strong><p>${esc(p.kind)}<br>${esc(p.source||'See data provenance')}${p.osm_id?'<br>OSM ID: '+esc(p.osm_id):''}</p>`;});}
function setLabelsVisible(visible){state.labelsVisible=!!visible;const toggle=$('#labels-toggle');if(toggle){toggle.checked=state.labelsVisible;toggle.setAttribute('aria-pressed',String(state.labelsVisible));}if(state.labels){if(state.labelsVisible)state.labels.addTo(map);else map.removeLayer(state.labels);state.labels.eachLayer(l=>l.setZIndexOffset?.(500));}}
function urbanTimeline(){const p=state.observationCounts?.years||{};return ['2019','2025'].map(y=>{const d=p[y]||{};return `<div class="timeline-card"><strong>${y}</strong><span>Jan–Mar</span><b>${d.median??'—'}</b><small>median clear observations / pixel</small><em>range ${d.minimum??'—'}–${d.maximum??'—'} · p10 ${d.p10??'—'} · p90 ${d.p90??'—'}</em></div>`}).join('')+`<p class="timeline-note">Clear observations are per-pixel counts from the masked six-band export; median and range summarize spatial variation, not scene counts. ${esc(state.observationCounts?.semantics||'')}</p>`;}
function createLayers(){for(const kind of Object.keys(state.overlays)){const features=state.data.features.filter(f=>f.properties.kind===kind);state.vectorLayers[kind]=L.geoJSON(features,{style:()=>({color:colors[kind],weight:kind==='boundary'?2:kind==='road'?.9:.75,opacity:kind==='boundary'?.9:.58,fillColor:'#b8c79b',fillOpacity:kind==='boundary'?.1:0,dashArray:kind==='boundary'?'5 5':null}),pointToLayer:(f,latlng)=>L.circleMarker(latlng,{radius:f.properties.place==='city'?4.5:f.properties.place==='town'?2.7:1.2,fillColor:colors.settlement,color:'#fffef2',weight:.8,fillOpacity:1}),onEachFeature:inspectFeature});}
 state.labelFeatures=state.data.features.filter(f=>f.properties.kind==='settlement'&&f.geometry.type==='Point').sort((a,b)=>({city:0,town:1,suburb:2,village:3}[a.properties.place]??4)-({city:0,town:1,suburb:2,village:3}[b.properties.place]??4));state.labels=L.featureGroup();refreshLabels();
}
function refreshLabels(){if(!state.labels)return;state.labels.clearLayers();const used=[],zoom=map.getZoom(),cap=zoom<10?15:zoom<12?35:90;for(const f of state.labelFeatures||[]){const ll=L.latLng(f.geometry.coordinates[1],f.geometry.coordinates[0]);if(!map.getBounds().contains(ll))continue;const xy=map.latLngToContainerPoint(ll);if(used.some(p=>Math.abs(xy.x-p.x)<105&&Math.abs(xy.y-p.y)<23))continue;used.push(xy);state.labels.addLayer(L.marker(ll,{icon:L.divIcon({className:'place-label',html:esc(f.properties.name),iconSize:[120,18]}),interactive:false,zIndexOffset:500}));if(used.length>=cap)break;}if(state.labelsVisible)state.labels.addTo(map);}
function updateRasterOpacity(){if(!Array.isArray(state.raster))return;const opacity=state.urbanMode==='after'?state.urbanBlend/100:state.urbanMode==='before'?0:1;state.raster.forEach((r,i)=>r.setOpacity(state.urbanMode==='candidates'?1:i===0?1:opacity));renderUrbanControls();renderLegend();}
function updateMap(){refreshLabels();Object.values(state.vectorLayers).forEach(l=>map.removeLayer(l));if(state.raster){(Array.isArray(state.raster)?state.raster:[state.raster]).forEach(r=>map.removeLayer(r));state.raster=null;}map.removeLayer(state.labels);const t=themeData(state.theme);const token=++state.rasterLoadToken;state.rasterPending=0;if(t){const srcs=state.theme==='urban'?urbanSources(t):[{image:t.image,opacity:.9}];state.rasterPending=srcs.length;$('#raster-load-count').textContent=`${srcs.length} raster${srcs.length===1?'':'s'} loading`;$('#map-loading').hidden=false;state.raster=srcs.map(x=>{const r=L.imageOverlay('data/'+x.image,t.bounds,{opacity:x.opacity,interactive:true}).addTo(map);const done=()=>{if(token!==state.rasterLoadToken)return;if(--state.rasterPending<=0){$('#map-loading').hidden=true;$('#raster-load-count').textContent='';}};r.once('load',done);r.once('error',()=>{$('#map-error').textContent='This raster could not load. Try the reference map or reload the page.';$('#map-error').hidden=false;done();});return r;});}else $('#map-loading').hidden=true;for(const [kind,l]of Object.entries(state.vectorLayers)){if(!state.overlays[kind])continue;if(t&&!['boundary','settlement','river'].includes(kind))continue;if(state.theme==='coastal'&&kind==='road')continue;if(t&&kind==='settlement'&&map.getZoom()<10)continue;l.addTo(map);}if(state.labelsVisible)state.labels.addTo(map);state.vectorLayers.boundary.bringToFront();if(map.hasLayer(state.vectorLayers.settlement))state.vectorLayers.settlement.bringToFront();if(state.labels)state.labels.eachLayer(l=>l.setZIndexOffset?.(500));renderUrbanControls();renderLegend();}

function selectTheme(id){if(!available(id)){showPage('limitations',id);return;}state.theme=id;if(id==='urban'){state.urbanMode='after';history.replaceState(null,'','#urban');}else if(location.hash)history.replaceState(null,'',location.pathname+location.search);showPage('explore');updateMap();if(id==='coastal')map.fitBounds(state.vectorLayers.coast.getBounds().pad(.12));updateInfo();if(state.view==='themes')renderThemes();$('#sidebar').classList.remove('open');}
function sourceDatasetCards(){const inv=state.inventory;const raster=state.thematic.map(t=>({name:t.title,source:t.source,url:t.sourceUrl,license:t.license,date:t.period,resolution:t.resolution,crs:t.inputCrs||t.crs||'See product metadata',processing:t.method,limitations:t.limitations,attribution:t.attribution,provenanceFile:t.provenanceFile}));return [...inv,...raster].map(d=>`<article class="dataset-card"><h3>${esc(d.name||d.dataset||d.dataset_name||'Geographic dataset')}</h3><div class="dataset-meta">${Object.entries({'Source':d.source,'Licence':d.license||d.licence,'Observation / release':d.date||d.period||d.observation_period,'Coverage':d.coverage||'Kozhikode and surroundings','Resolution / scale':d.resolution||d.scale||'Variable source detail','Source CRS':d.crs||'EPSG:4326'}).map(([k,v])=>`<div><strong>${k}</strong><p>${esc(typeof v==='object'?JSON.stringify(v):v||'Not specified')}</p></div>`).join('')}</div><p><b>Processing:</b> ${esc(d.processing||'See reproducible pipeline.')}</p><p><b>Limitations:</b> ${esc(d.limitations||'Not a legal or cadastral reference.')}</p>${d.attribution?`<p><b>Attribution:</b> ${esc(d.attribution)}</p>`:''}${d.provenanceFile==='landslide-provenance.json'?`<div class="rights-warning"><strong>Rights warning:</strong> ${GSI_RIGHTS_WARNING}</div>`:''}${d.provenanceFile?`<a href="data/${esc(d.provenanceFile)}" download>Download processing record</a>`:''}${/^https?:\/\//.test(d.url||d.source_url||'')?`<a href="${esc(d.url||d.source_url)}" target="_blank" rel="noopener noreferrer">Open source documentation ↗</a>`:''}</article>`).join('');}
const methodology=`<div class="eyebrow">HOW TO READ THIS ATLAS</div><h2>Good maps start with good questions.</h2><p>This atlas supports geographic exploration, not prediction. It uses a small static application, published vector features and pre-rendered raster products. There is no private API key and no analytical backend.</p><h3>A consistent frame</h3><p>Vector exchange uses WGS 84 longitude/latitude (EPSG:4326). Web maps and exports use Web Mercator (EPSG:3857). Metric terrain derivatives, where available, use UTM zone 43N (EPSG:32643). Distances and scale are not calculated directly in geographic degrees.</p><h3>Colour follows meaning</h3><p>Olive dashed lines show district boundaries; dark points identify settlements; muted ochre lines show major roads; blue lines show water. Land cover uses the product’s categorical legend, not a continuous ranking. Elevation and slope use fixed, ordered classes with units. Missing raster pixels are transparent and must not be interpreted as the lowest value.</p><h3>Evidence before interpretation</h3><p>Land-cover classes are model outputs, not field observations. Surface elevation is not necessarily bare-earth terrain. Coastlines imply neither a hazard zone nor a surveyed high-water line. Population choropleths require matched census boundaries and meaningful denominators; urban-change maps require seasonally and radiometrically comparable observations plus validation.</p><h3>Landslide susceptibility</h3><p>The GSI 2022 susceptibility layer is a published relative-zonation product. Its classes are not probabilities, forecasts, live warnings, safe-land designations or site assessments. Unmapped areas are unknown, not safe; consult the official KSDMA source notes and qualified professionals for decisions.</p><h3>Source to screen</h3><p>The pipeline retains original inputs, records source URLs and parameters, validates geometry, checks longitude/latitude bounds, detects duplicates, and records processing. Simplification and raster aggregation are display decisions, not improvements in source accuracy. Inspect the source notes for each layer’s actual resolution and limitations.</p><h3>Print with context</h3><p>Exports include title, legend, scale, projection, provenance and observation period. The vector layout omits online basemap tiles. PNG uses the chosen A4 or A3 page at 300 dpi. SVG retains vector features and embeds available rasters. Direct PDF downloads support A4/A3 and portrait/landscape. Scale varies in Web Mercator and is valid at the map centre.</p><h3>Accessible exploration</h3><p>Layer names, categorical labels, line styles and symbols accompany colour. Controls are keyboard reachable, status messages are announced, and search provides an alternative to visually locating named features. Maps are north-up. No individual-level or sensitive personal information is included.</p>`;
function showPage(page,context=''){
 const isExplore=page==='explore';document.querySelectorAll('[data-explore-only]').forEach(node=>node.hidden=!isExplore);document.querySelector('.intro').hidden=!isExplore;document.querySelector('.explore-shortcuts').hidden=!isExplore;const route=isExplore?(state.theme==='urban'?'urban':state.theme==='reference'?'explore':state.theme):page;if(location.hash!=='#'+route)history.replaceState(null,'','#'+route);$('#explore-page').hidden=!isExplore;$('#document-page').hidden=isExplore;document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(isExplore){requestAnimationFrame(()=>map.invalidateSize());return;}
 let content='';if(page==='sources')content=`<div class="eyebrow">THE EVIDENCE BEHIND THE MAP</div><h2>Nothing without a source.</h2><p>These are the datasets actually loaded by this atlas. A release date is not necessarily an observation date. External basemap tiles provide context and are not a substitute for a dated analytical dataset.</p>${sourceDatasetCards()}<article class="dataset-card"><h3>Context basemap</h3><p><a href="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer" target="_blank" rel="noopener">Esri World Light Gray Base</a>. © Esri, HERE, Garmin, OpenStreetMap contributors and the GIS user community. A legacy context basemap in mature support, no longer updated; it is not evidence of current conditions. Variable capture dates, detail and completeness. Served online; not bundled or included in exports. Network or provider failure may remove this context without affecting bundled layers.</p></article><article class="dataset-card"><h3>Interactive 3D relief</h3><p>The existing Copernicus DEM GLO-30 public 2021 DSM is averaged to an 80 × 64 grid in UTM zone 43N (EPSG:32643), with approximately 834 × 1,180 m grid spacing. Heights are metres above EGM2008. District exterior, missing and negative source values are omitted, never assigned zero. Surface height includes vegetation and buildings; this coarsened display is not a survey.</p><p>Vertical exaggeration is clearly labelled and adjustable from 1× to 10×. The elevation legend retains the same metre thresholds as the 2D elevation layer. The rotating model is a terrain visualisation, not evidence of urban change.</p><p><a href="data/terrain-3d.json" download>Download the 3D display grid and provenance</a> · <a href="https://registry.opendata.aws/copernicus-dem/" target="_blank" rel="noopener">Copernicus DEM source and licence</a> · <a href="vendor/three/LICENSE.txt" target="_blank" rel="noopener">Three.js software licence (MIT)</a></p><p>Three.js r180 provides WebGL rendering and orbit interaction. A local canvas-based 3D renderer is used where WebGL is unavailable; both render the same measured heights. 3D rendering pauses off-screen. Reduced-motion preferences disable automatic rotation.</p><p>The elevation-profile lab samples nearest valid cells on this same coarse display grid along a straight projected line. Distance is computed in UTM 43N metres and shown in kilometres. Missing cells remain gaps; these profiles are not road routes or surveys. Contours are intersections of the display mesh with fixed 50, 200, 500, 1,000, 1,500 and 2,000 m planes. They are generalised display contours, not survey contours.</p></article><article class="dataset-card"><h3>Kerala regional locator & geographic story</h3><p>The opening and first story chapter use the real Kerala state boundary from geoBoundaries gbOpen ADM1 (2011 boundary representation, release commit 9469f09). It is simplified with 500 m topology-preserving tolerance in UTM 43N. The atlas’s existing district geometry is unchanged. Different source generalisations may leave tiny state/district edge mismatches; this locator is not a legal survey.</p><p>Attribution: geoBoundaries / DataMeet India community & Election Commission of India, <a href="https://creativecommons.org/licenses/by/2.5/in/" target="_blank" rel="noopener">CC BY 2.5 IN</a>. <a href="data/kerala-region-source.json" download>Regional locator provenance</a> · <a href="data/kerala-region.geojson" download>Download locator boundaries</a> · <a href="https://www.geoboundaries.org/api/current/gbOpen/IND/ADM1/" target="_blank" rel="noopener">Official source</a>.</p><p>The water chapter uses existing OpenStreetMap geometry, not live hydrological measurements. The height chapter uses the same fixed legend as the 3D scene and 2D elevation layer. The satellite chapter shows the existing January–March 2019/2025 composites at identical display extent. No decorative particles imply real flow or change.</p></article>`;
 else if(page==='methodology')content=methodology;
 else if(page==='about')content=`<div class="eyebrow">A PLACE, IN LAYERS</div><h2>Kozhikode, with a closer look.</h2><p>A public-facing geographic atlas of Kozhikode district, Kerala, India. Designed for students, researchers, residents and anyone curious about how the Malabar coast connects to its inland landscapes.</p><h3>Small by design. Open by principle.</h3><p>The application is plain HTML, CSS and JavaScript with Leaflet 1.9.4. Local GeoJSON and lightweight raster images keep the map usable on ordinary computers, with no login or API key. Python processing scripts, validation tests and technical documentation are maintained with the project source.</p><h3>Explore thoughtfully</h3><p>This is an exploratory publication, not an official administrative, cadastral, navigation, emergency-response or engineering product. Source licences continue to apply. Boundary representations may differ from current official records.</p>`;
 else content=`<div class="eyebrow">THE EDGES OF WHAT WE KNOW</div><h2>${context==='urban'?'Change needs comparable evidence.':context==='population'?'People need the right denominator.':'Every atlas has its limits.'}</h2><p>The atlas intentionally withholds maps that the available evidence cannot support. A missing layer is more honest than a convincing-looking invention.</p><h3>Urban change — exploratory signals</h3><p>Jan–Mar 2019 and Jan–Mar 2025 Sentinel-2 comparisons are available as natural-colour imagery plus candidate signals. Ground validation and independent positional accuracy assessment are not done. Candidate raw pixels before the minimum mapping-unit threshold vary strongly by probability threshold: 0.5 = 15,021; 0.6 = 4,224; 0.7 = 530. These are threshold-dependent candidate pixels, not a verified area estimate.</p><h3>Landslide susceptibility — exploratory only</h3><p>GSI 2022 zones describe relative susceptibility at the source map’s scale and classification. They do not predict when or where a landslide will occur, and they do not replace drainage, geology, field inspection, engineering or emergency information. Unmapped is not safe; this atlas provides no live warning.</p><h3>Population & socioeconomic maps — not available</h3><p>No verified district subunit table joined to matching geographic units and denominators is bundled. A choropleth of raw population totals would be misleading. Add census geography, dates, rates or densities, missing-value handling and ecological interpretation cautions before enabling it.</p><h3>Geographic coverage and accuracy</h3><p>Public reference boundaries are not legal boundaries. OpenStreetMap coverage is uneven, and mapped features are not an exhaustive inventory. No coastline-derived flood or erosion designation is made. Rasters, when available, are downsampled display products and may extend outside the district; their original pixel size does not imply screen-level accuracy.</p><h3>Print and offline use</h3><p>External context tiles need an internet connection. Exports use bundled data, not third-party tile screenshots, and omit basemap labels that are not in the feature extract. Raster exports do not restore original resolution. SVG rasters are embedded, while vector features remain editable. PDF page dimensions follow the selected paper size and orientation.</p>`;
 $('#document-page').innerHTML=content+'<button class="back-link" id="back-explore">← Back to the atlas</button>';$('#back-explore').onclick=()=>showPage('explore');const heading=$('#document-page h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
}
function search(){const q=$('#search').value.trim().toLowerCase();if(state.view!=='themes')setCatalogue('themes');renderThemes(q);if(q.length<2){$('#search-results').innerHTML='';return;}const seenNames=new Set();const matches=state.data.features.filter(f=>f.properties.kind!=='boundary'&&(f.properties.name||'').toLowerCase().includes(q)).sort((a,b)=>{const score=f=>(f.properties.name.toLowerCase()===q?0:10)+(f.properties.kind==='settlement'?0:5);return score(a)-score(b)||a.properties.name.localeCompare(b.properties.name);}).filter(f=>{const key=f.properties.kind+'|'+f.properties.name.toLowerCase();if(seenNames.has(key))return false;seenNames.add(key);return true;}).slice(0,7);$('#search-results').innerHTML=matches.length?matches.map((f,i)=>`<button data-result="${i}">${esc(f.properties.name)} <small>· ${esc(f.properties.kind)}</small></button>`).join(''):'<p>No named places match. Try another spelling.</p>';$('#search-results').querySelectorAll('button').forEach(b=>b.onclick=()=>{const f=matches[+b.dataset.result];const l=L.geoJSON(f);const bounds=l.getBounds();map.fitBounds(bounds.pad(.4),{maxZoom:13});$('#search').value='';$('#search-results').innerHTML='';renderThemes();$('#sidebar').classList.remove('open');L.popup().setLatLng(bounds.getCenter()).setContent(`<strong>${esc(f.properties.name)}</strong><br>${esc(f.properties.kind)}<br>${esc(f.properties.source)}`).openOn(map);});}
function loadBookmarks(){try{const saved=JSON.parse(localStorage.getItem('kozhikode-atlas-bookmarks')||'[]');state.bookmarks=Array.isArray(saved)?saved.filter(b=>b&&typeof b.name==='string'&&Array.isArray(b.center)&&b.center.length===2&&b.center.every(Number.isFinite)&&Number.isFinite(b.zoom)):[]}catch(e){state.bookmarks=[]}renderBookmarks();}
function renderBookmarks(){const s=$('#bookmark-select');if(!s)return;s.innerHTML='<option value="">Bookmarks…</option>'+state.bookmarks.map((b,i)=>`<option value="${i}">${esc(b.name)}</option>`).join('');}
function saveBookmark(){const d=$('#bookmark-dialog');$('#bookmark-name').value='';d.showModal();$('#bookmark-name').focus();}
function persistBookmark(name){const b={name:name.trim(),center:[map.getCenter().lat,map.getCenter().lng],zoom:map.getZoom(),theme:state.theme,urbanMode:state.urbanMode,urbanBlend:state.urbanBlend,labelsVisible:state.labelsVisible};try{const next=state.bookmarks.filter(x=>x.name!==b.name);next.push(b);localStorage.setItem('kozhikode-atlas-bookmarks',JSON.stringify(next));state.bookmarks=next;renderBookmarks();$('#bookmark-select').value=String(state.bookmarks.length-1);$('#bookmark-delete').disabled=false;notify('View saved in this browser.');return true;}catch(e){notify('This browser could not save the view. Allow site storage and try again.');return false;}}
function recallBookmark(index){if(index==='')return;const b=state.bookmarks[+index];if(!b)return;state.theme=themeDefs.some(t=>t.id===b.theme)&&available(b.theme)?b.theme:'reference';state.urbanMode=['before','after','candidates'].includes(b.urbanMode)?b.urbanMode:'after';state.urbanBlend=Number.isFinite(b.urbanBlend)?Math.max(0,Math.min(100,b.urbanBlend)):100;setLabelsVisible(b.labelsVisible!==false);map.setView(b.center,b.zoom);showPage('explore');updateMap();updateInfo();renderThemes();$('#bookmark-delete').disabled=false;notify('View restored: '+b.name);}
function deleteBookmark(){const s=$('#bookmark-select'),i=+s.value;if(s.value===''||!Number.isInteger(i)||!state.bookmarks[i])return;if(!confirm('Delete the saved view “'+state.bookmarks[i].name+'”?'))return;try{const next=state.bookmarks.filter((_,n)=>n!==i);localStorage.setItem('kozhikode-atlas-bookmarks',JSON.stringify(next));state.bookmarks=next;renderBookmarks();$('#bookmark-delete').disabled=true;notify('Saved view deleted.');}catch(e){notify('Could not update saved views. Allow site storage and try again.');}}
