 map.on('moveend',()=>{refreshLabels();const c=map.getCenter();$('#coordinates').textContent=c.lat.toFixed(4)+'° N  '+c.lng.toFixed(4)+'° E';});map.on('mousemove',e=>$('#coordinates').textContent=e.latlng.lat.toFixed(4)+'° N  '+e.latlng.lng.toFixed(4)+'° E');map.on('zoomend',()=>{if(themeData(state.theme))updateMap();});map.on('click',e=>{if(themeData(state.theme))$('#feature-box').innerHTML=`<span class="eyebrow">Map location</span><strong>${e.latlng.lat.toFixed(5)}° N</strong><p>${e.latlng.lng.toFixed(5)}° E<br>Use Inspect map for numeric values and dated sources. Raster readings use an approximately 100 m query grid.</p>`;});
 document.querySelectorAll('[data-urban-mode]').forEach(x=>x.onclick=()=>setUrbanMode(x.dataset.urbanMode));$('#urban-example').onclick=()=>{if(state.theme==='urban'){map.setView([11.2440,75.8339],13);$('#raster-caption').textContent='Visual example · compare the linear corridor';}};$('#urban-blend').oninput=()=>{if(state.urbanMode!=='after')return;state.urbanBlend=+$('#urban-blend').value;if(state.theme==='urban'){updateRasterOpacity();updateInfo();}};$('#reset-map').onclick=()=>{map.fitBounds(state.bounds,{padding:[36,36],maxZoom:11.5});notify('Map reset to Kozhikode district.');};$('#search').addEventListener('input',search);$('#maps-tab').onclick=()=>setCatalogue('themes');$('#overlays-tab').onclick=()=>setCatalogue('overlays');$('#source-link').onclick=()=>showPage('sources');$('#mobile-layers').onclick=()=>$('#sidebar').classList.toggle('open');$('#mobile-close').onclick=()=>$('#sidebar').classList.remove('open');$('#close-info').onclick=()=>{$('#info-panel').classList.remove('open');if(innerWidth>1050){$('#explore-page').classList.add('notes-hidden');map.invalidateSize();}};$('#info-toggle').onclick=()=>{$('#info-panel').classList.toggle('open');$('#info-toggle').setAttribute('aria-expanded',String($('#info-panel').classList.contains('open')));};
