function blobData(blob){return new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob);});}
async function buildSVG(){
 const portrait=$('#orientation').value==='portrait',W=portrait?990:1400,H=portrait?1400:990;const margin=50,top=145,bottom=210,mw=W-margin*2,mh=H-top-bottom;const bounds=map.getBounds();const a=L.CRS.EPSG3857.project(bounds.getSouthWest()),b=L.CRS.EPSG3857.project(bounds.getNorthEast());const s=Math.min(mw/(b.x-a.x),mh/(b.y-a.y)),cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;const point=c=>{const p=L.CRS.EPSG3857.project(L.latLng(c[1],c[0]));return [margin+mw/2+(p.x-cx)*s,top+mh/2-(p.y-cy)*s];};
 const line=coords=>coords.map((c,i)=>(i?'L':'M')+point(c).map(n=>n.toFixed(2)).join(',')).join(' ');
 let features='';for(const f of state.data.features){const k=f.properties.kind,layer=state.vectorLayers[k];if(!state.overlays[k]||!layer||!map.hasLayer(layer))continue;const g=f.geometry;const style=`stroke="${colors[k]}" stroke-width="${k==='boundary'?2:1.2}" fill="${k==='boundary'?'#e5ebda':'none'}" fill-opacity="${k==='boundary'&&!themeData(state.theme)?'.32':'0'}" ${k==='boundary'?'stroke-dasharray="6 5"':''}`;if(g.type==='Point'){const [x,y]=point(g.coordinates);features+=`<circle cx="${x}" cy="${y}" r="3" fill="${colors[k]}" stroke="#fffef4" stroke-width="1"/>`;if(false)features+=`<text x="${x+7}" y="${y-4}" font-family="Arial" font-size="10" fill="#344e36">${esc(f.properties.name)}</text>`;}else if(g.type==='LineString')features+=`<path d="${line(g.coordinates)}" ${style}/>`;else if(g.type==='MultiLineString')features+=`<path d="${g.coordinates.map(line).join(' ')}" ${style}/>`;else if(g.type==='Polygon')features+=`<path d="${g.coordinates.map(c=>line(c)+'Z').join(' ')}" ${style} fill-rule="evenodd"/>`;else if(g.type==='MultiPolygon')features+=`<path d="${g.coordinates.flatMap(p=>p.map(c=>line(c)+'Z')).join(' ')}" ${style} fill-rule="evenodd"/>`;}
 if(state.labelsVisible)state.labels.eachLayer(l=>{const ll=l.getLatLng(),[x,y]=point([ll.lng,ll.lat]);features+=`<text x="${x+5}" y="${y-4}" font-family="Arial" font-size="11" fill="#344e36" stroke="#fffef7" stroke-width="2" paint-order="stroke">${l.options.icon.options.html}</text>`;});
 for(const f of window.atlas?.elections?.exportFeatures()||[]){const g=f.geometry;const rings=g.type==='Polygon'?g.coordinates:g.coordinates.flat();features+=`<path d="${rings.map(c=>line(c)+'Z').join(' ')}" stroke="#576d45" stroke-width="1.5" stroke-dasharray="5 4" fill="none"/>`;}
 let raster='';const t=themeData(state.theme);if(t){const srcs=state.theme==='urban'?urbanSources(t):[{image:t.image,opacity:.9}];const p1=point([t.bounds[0][1],t.bounds[1][0]]),p2=point([t.bounds[1][1],t.bounds[0][0]]);for(const src of srcs){const response=await fetch('data/'+src.image);if(!response.ok)throw Error('Raster unavailable for export.');const data=await blobData(await response.blob());raster+=`<image href="${data}" x="${p1[0]}" y="${p1[1]}" width="${p2[0]-p1[0]}" height="${p2[1]-p1[1]}" preserveAspectRatio="none" opacity="${src.opacity}"/>`;}}
 const centre=map.getCenter();const targetKm=(mw*.2/s)*Math.cos(centre.lat*Math.PI/180)/1000;const base=10**Math.floor(Math.log10(targetKm));const barKm=[1,2,5,10].map(x=>x*base).filter(x=>x<=targetKm).pop()||base;const barWidth=(barKm*1000/Math.cos(centre.lat*Math.PI/180))*s;const ly=H-bottom+32;const legend=[...activeLegend(),...(window.atlas?.elections?.exportFeatures().length?[{color:'#576d45',label:'MLA constituency borders (indicative)'}]:[])].map((l,i)=>{const x=margin+(i%(portrait?3:5))*(portrait?290:260),y=ly+Math.floor(i/(portrait?3:5))*22;return `<rect x="${x}" y="${y-9}" width="14" height="9" fill="${esc(l.color)}"/><text x="${x+22}" y="${y}" font-size="11" fill="#5b6b4e">${esc(l.label)}</text>`;}).join('');
 const sourceText=(t?`${t.source} · ${t.period} · ${t.resolution}`:'Boundary & reference data: see project inventory · © OpenStreetMap contributors where applicable')+(window.atlas?.elections?.exportFeatures().length?' · Constituencies: DataMeet / ECI-derived, CC BY 2.5 India':'');
 return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><title>${esc($('#export-title').value)}</title><desc>Exploratory map of Kozhikode. Web Mercator EPSG:3857. Scale valid at map centre. ${esc(sourceText)}${state.theme==='landslide'?' Landslide limitations: GSI 2022 susceptibility zones are relative classes, not probabilities, forecasts, live warnings, safe-land designations or site assessments. Unmapped areas are unknown, not safe. The layer is district-scale and must not be used as a site assessment or emergency decision tool. Official context: Kerala State Disaster Management Authority.':''}</desc><rect width="100%" height="100%" fill="#fffef7"/><text x="50" y="42" font-family="Arial" font-size="11" letter-spacing="3" fill="#7c8d68">KOZHIKODE ATLAS / KERALA, INDIA</text><text x="50" y="97" font-family="Georgia" font-size="38" fill="#2f4732">${esc($('#export-title').value)}</text><text x="50" y="123" font-family="Arial" font-size="12" fill="#788568">${esc(state.theme==='urban'?(state.urbanMode==='before'?'Before · 2019':state.urbanMode==='candidates'?'Candidate built-up gains · model signals':`2019 → 2025 · ${state.urbanBlend}% after`):'A place, in layers. An exploratory geographic publication.')}</text><defs><clipPath id="mapclip"><rect x="${margin}" y="${top}" width="${mw}" height="${mh}"/></clipPath></defs><rect x="${margin}" y="${top}" width="${mw}" height="${mh}" fill="#f2f4e9" stroke="#d5dec9"/><g clip-path="url(#mapclip)">${raster}${features}</g><g font-family="Arial"><text x="${W-80}" y="${top+30}" font-size="12" fill="#415b37">N</text><path d="m${W-76} ${top+39} -7 26 7-6 7 6Z" fill="#415b37"/><rect x="${margin+18}" y="${top+mh-55}" width="${barWidth+24}" height="40" fill="#fffef7" opacity=".9"/><path d="M${margin+30} ${top+mh-33}h${barWidth}" stroke="#344c35" stroke-width="3"/><text x="${margin+30}" y="${top+mh-18}" font-size="10" fill="#415b37">0</text><text x="${margin+30+barWidth}" y="${top+mh-18}" font-size="10" text-anchor="end" fill="#415b37">${barKm>=1?barKm+' km':Math.round(barKm*1000)+' m'}</text>${legend}${window.atlas?.elections?.exportFeatures().length?`<text x="50" y="${H-115}" font-size="10" fill="#71815d">Constituency borders: DataMeet / ECI-derived · CC BY 2.5 India · indicative, not legal boundaries</text>`:''}<text x="50" y="${H-95}" font-size="10" fill="#71815d">${esc(sourceText).slice(0,180)}</text><text x="50" y="${H-75}" font-size="10" fill="#71815d">Display projection: Web Mercator (EPSG:3857) · Scale valid at ${centre.lat.toFixed(2)}° N · North up</text><text x="50" y="${H-55}" font-size="10" fill="#71815d">${esc(t?t.method:'Unclassified reference features; not a legal boundary. No online basemap tiles in export.').slice(0,170)}</text><text x="50" y="${H-35}" font-size="10" fill="#71815d">${esc(state.theme==='landslide'?'GSI 2022 susceptibility only. Unmapped is not safe; not a live warning or site assessment.':'Missing raster pixels are transparent. Not for navigation, hazard assessment or site-level decisions.')}</text></g></svg>`;
}
function saveBlob(blob,ext){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kozhikode-'+state.theme+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function makePdf(svg){const image=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));await new Promise((ok,no)=>{image.onload=ok;image.onerror=no;image.src=url});const portrait=$('#orientation').value==='portrait',a3=$('#paper-size').value==='A3',pw=portrait?(a3?841.89:595.28):(a3?1190.55:841.89),ph=portrait?(a3?1190.55:841.89):(a3?841.89:595.28),canvas=document.createElement('canvas');canvas.width=portrait?2480:3508;canvas.height=portrait?3508:2480;const ctx=canvas.getContext('2d');ctx.fillStyle='#fffef7';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const raw=atob(canvas.toDataURL('image/jpeg',.88).split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const enc=t=>String(t).replace(/[^\x20-\x7e]/g,' ').replaceAll('\\','\\\\').replaceAll('(','\\(').replaceAll(')','\\)');const lines=[$('#export-title').value,`Kozhikode Atlas · ${state.theme==='urban'?'Jan–Mar 2019 / Jan–Mar 2025':'reference map'}`,`Source: ${themeData(state.theme)?.source||'Atlas inventory / OpenStreetMap contributors'}`,`Projection: Web Mercator EPSG:3857 · Scale valid at map centre`,`Legend: ${activeLegend().map(x=>x.label).join(' · ')}`,`Notes: ${state.theme==='landslide'?'GSI 2022 susceptibility only. Unmapped is not safe; not a live warning or site assessment.':(themeData(state.theme)?.method||'Exploratory reference map; not for navigation or site-level decisions.')}`];const content=`q ${pw} 0 0 ${ph} 0 0 cm /Im1 Do Q`;const objs=[`<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length} >>\nstream`, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Catalog /Pages 5 0 R >>','<< /Type /Pages /Kids [6 0 R] /Count 1 >>',`<< /Type /Page /Parent 5 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im1 1 0 R >> /Font << /F1 3 0 R >> >> /Contents 2 0 R >>`];const te=t=>new TextEncoder().encode(t),chunks=[te('%PDF-1.4\n')];let offset=chunks[0].length,offs=[0];for(let i=0;i<objs.length;i++){offs[i+1]=offset;const head=te(`${i+1} 0 obj\n${objs[i]}\n`);chunks.push(head);offset+=head.length;if(i===0){chunks.push(bytes,te('\nendstream\n'));offset += bytes.length + '\nendstream\n'.length;}const tail=te('endobj\n');chunks.push(tail);offset+=tail.length;}const x=offset,trailer='xref\n0 7\n0000000000 65535 f \n'+offs.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 7 /Root 4 0 R >>\nstartxref\n'+x+'\n%%EOF';chunks.push(te(trailer));return new Blob(chunks,{type:'application/pdf'});}
async function exportMap(format){if(state.theme==='landslide'){$('#export-status').textContent='GSI layer export is withheld: the supplied download has no explicit reuse licence. Use the official KSDMA map or obtain written permission. Other atlas exports remain available.';return;}$('#export-status').textContent='Preparing your attributed map…';try{const svg=await buildSVG();if(format==='svg')saveBlob(new Blob([svg],{type:'image/svg+xml'}),'svg');else if(format==='png'){const image=new Image();const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));await new Promise((ok,no)=>{image.onload=ok;image.onerror=no;image.src=url;});const a3=$('#paper-size').value==='A3',portrait=$('#orientation').value==='portrait';const w=a3?4961:3508,h=a3?3508:2480;const canvas=document.createElement('canvas');canvas.width=portrait?h:w;canvas.height=portrait?w:h;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const blob=await new Promise(ok=>canvas.toBlob(ok,'image/png'));if(!blob)throw Error('PNG could not be generated.');saveBlob(await pngDPI(blob,300),'png');}else{saveBlob(await makePdf(svg),'pdf');}$('#export-status').textContent='Your '+format.toUpperCase()+' map is ready.';}catch(e){$('#export-status').textContent='Export failed: '+(e.message||'Image rendering was unavailable. Try SVG.');}}
