async function pngDPI(blob,dpi){
 const data=new Uint8Array(await blob.arrayBuffer()),ppm=Math.round(dpi/0.0254);
 const chunk=new Uint8Array(21),view=new DataView(chunk.buffer);view.setUint32(0,9);chunk.set([112,72,89,115],4);view.setUint32(8,ppm);view.setUint32(12,ppm);chunk[16]=1;
 let crc=0xffffffff;for(const byte of chunk.subarray(4,17)){crc^=byte;for(let bit=0;bit<8;bit++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}view.setUint32(17,(crc^0xffffffff)>>>0);
 const parts=[data.subarray(0,8)],original=new DataView(data.buffer);let offset=8;
 while(offset+12<=data.length){const length=original.getUint32(offset),type=String.fromCharCode(...data.subarray(offset+4,offset+8));if(type!=='pHYs')parts.push(data.subarray(offset,offset+12+length));if(type==='IHDR')parts.push(chunk);offset+=12+length;}
 return new Blob(parts,{type:'image/png'});
}
